      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/banking/actions.ts\" start_line=\"1\" end_line=\"70\">\n  1|import { z } from 'zod';\n  2|import { appDb } from '../db';\n  3|import { HttpError } from '../auth';\n  4|import { person } from '../people';\n  5|import { authorizeTransfer } from './authorization';\n  6|import { dispatchTransfer } from './dispatch';\n  7|import { recordEvent } from '../telemetry';\n  8|import type { ActionResult, ToolContext } from '../types';\n  9|export const transferSchema = z\n 10|  .object({\n 11|    fromAccountId: z.string().min(1),\n 12|    toAccountId: z.string().min(1),\n 13|    amountCents: z.number().int().positive().max(10000000),\n 14|    concept: z.string().max(200),\n 15|  })\n 16|  .strict();\n 17|export async function transferMoney(ctx: ToolContext, args: unknown): Promise<ActionResult> {\n 18|  if (person(ctx.userId)?.role !== 'customer')\n 19|    throw new HttpError(403, 'A customer account is required.');\n 20|  const input = transferSchema.parse(args),\n 21|    db = appDb();\n 22|  const previous = db\n 23|    .prepare('SELECT user_id,payload FROM intents WHERE id=?')\n 24|    .get(ctx.intentId) as { user_id: string; payload: string } | undefined;\n 25|  if (previous && (previous.user_id !== ctx.userId || previous.payload !== JSON.stringify(input)))\n 26|    throw new HttpError(409, 'This intent belongs to a different payload.');\n 27|  db.prepare('INSERT OR IGNORE INTO intents VALUES(?,?,?,?,?,?,?,?,?,?)').run(\n 28|    ctx.intentId,\n 29|    ctx.userId,\n 30|    ctx.conversationId,\n 31|    ctx.runId,\n 32|    JSON.stringify(input),\n 33|    'created',\n 34|    null,\n 35|    null,\n 36|    null,\n 37|    new Date().toISOString(),\n 38|  );\n 39|  const permission = await authorizeTransfer(ctx, input);\n 40|  if (permission) return permission;\n 41|  db.prepare('UPDATE intents SET status=? WHERE id=?').run('processing', ctx.intentId);\n 42|  recordEvent(ctx, 'transfer.started', { status: 'processing', input, intentId: ctx.intentId });\n 43|  try {\n 44|    const operation = await dispatchTransfer(ctx, input);\n 45|    db.prepare('UPDATE intents SET status=?,operation_id=?,error=NULL WHERE id=?').run(\n 46|      'completed',\n 47|      operation.id,\n 48|      ctx.intentId,\n 49|    );\n 50|    recordEvent(ctx, 'transfer.completed', {\n 51|      status: 'completed',\n 52|      operation,\n 53|      intentId: ctx.intentId,\n 54|    });\n 55|    return { status: 'completed', operation, intentId: ctx.intentId };\n 56|  } catch (e) {\n 57|    const message = e instanceof Error ? e.message : 'Transfer error';\n 58|    db.prepare('UPDATE intents SET status=?,error=? WHERE id=?').run(\n 59|      'failed',\n 60|      message,\n 61|      ctx.intentId,\n 62|    );\n 63|    recordEvent(ctx, 'transfer.failed', {\n 64|      status: 'failed',\n 65|      error: message,\n 66|      intentId: ctx.intentId,\n 67|    });\n 68|    return { status: 'failed', error: message, intentId: ctx.intentId };\n 69|  }\n 70|}\n</file-view>",
