      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/operator/view.ts\" start_line=\"1\" end_line=\"23\">\n  1|import { appDb } from '../db';\n  2|import { person } from '../people';\n  3|import { HttpError } from '../auth';\n  4|export async function caseDetail(operatorId: string, id: string) {\n  5|  if (person(operatorId)?.role !== 'operator') throw new HttpError(403, 'Operator role required.');\n  6|  const db = appDb();\n  7|  const incident = db.prepare('SELECT * FROM incidents WHERE id=?').get(id) as any;\n  8|  if (!incident) throw new HttpError(404, 'Case not found.');\n  9|  const lastMessage = db\n 10|    .prepare(\n 11|      'SELECT * FROM messages WHERE conversation_id=? ORDER BY created_at DESC,rowid DESC LIMIT 1',\n 12|    )\n 13|    .get(incident.conversation_id);\n 14|  return {\n 15|    incident,\n 16|    customer: person(incident.user_id),\n 17|    lastMessage,\n 18|    history: [],\n 19|    events: [],\n 20|    intents: [],\n 21|    bank: null,\n 22|  };\n 23|}\n</file-view>",
