      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/retrieval/search.ts\" start_line=\"1\" end_line=\"26\">\n  1|import { appDb } from '../db';\n  2|import { config } from '../config';\n  3|import { embedTexts } from './embeddings';\n  4|import { allChunks } from './store';\n  5|import type { SearchResult } from '../types';\n  6|export async function searchDocuments(\n  7|  query: string,\n  8|  role = 'customer',\n  9|  limit = 5,\n 10|): Promise<SearchResult[]> {\n 11|  const meta = appDb().prepare('SELECT value FROM meta WHERE key=?').get('index-model') as\n 12|    { value: string } | undefined;\n 13|  if (!meta) throw new Error('No document index. Run npm run setup or npm run ingest.');\n 14|  if (meta.value !== config.embeddingModel)\n 15|    throw new Error('The model does not match the index. Re-ingest the documents.');\n 16|  const [queryVector] = await embedTexts([query]);\n 17|  return allChunks()\n 18|    .filter((c) => role === 'operator' || c.audience === 'public')\n 19|    .map(({ vector, ...c }) => {\n 20|      if (vector!.length !== queryVector.length) throw new Error('Incompatible embedding dimensions.');\n 21|      const score = vector!.reduce((sum, v, i) => sum + v * queryVector[i], 0);\n 22|      return { ...c, score };\n 23|    })\n 24|    .sort((a, b) => b.score - a.score)\n 25|    .slice(0, limit);\n 26|}\n</file-view>",
