      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/retrieval/store.ts\" start_line=\"1\" end_line=\"85\">\n  1|import { appDb } from '../db';\n  2|import { config } from '../config';\n  3|import { vectorBuffer, readVector, embeddingKey } from './embeddings';\n  4|import type { Chunk } from '../types';\n  5|export type IndexDump = {\n  6|  format: 1;\n  7|  model: string;\n  8|  dimensions: number;\n  9|  chunks: (Omit<Chunk, 'vector'> & { vectorBase64: string })[];\n 10|};\n 11|export function replaceChunks(chunks: Chunk[], settings: { model: string; dimensions: number }) {\n 12|  const db = appDb();\n 13|  db.transaction(() => {\n 14|    db.exec('DELETE FROM chunks');\n 15|    const insert = db.prepare('INSERT INTO chunks VALUES(?,?,?,?,?,?,?,?,?)');\n 16|    for (const c of chunks) {\n 17|      if (c.vector?.length !== settings.dimensions) throw new Error('Incomplete index.');\n 18|      insert.run(\n 19|        c.id,\n 20|        c.documentId,\n 21|        c.text,\n 22|        c.title,\n 23|        c.version,\n 24|        c.validFrom,\n 25|        c.validTo,\n 26|        c.audience,\n 27|        vectorBuffer(c.vector),\n 28|      );\n 29|    }\n 30|    db.prepare('INSERT OR REPLACE INTO meta VALUES(?,?)').run('index-model', settings.model);\n 31|    db.prepare('INSERT OR REPLACE INTO meta VALUES(?,?)').run(\n 32|      'index-dimensions',\n 33|      String(settings.dimensions),\n 34|    );\n 35|  })();\n 36|}\n 37|export function allChunks(): Chunk[] {\n 38|  return (appDb().prepare('SELECT * FROM chunks ORDER BY id').all() as any[]).map((r) => ({\n 39|    id: r.id,\n 40|    documentId: r.document_id,\n 41|    text: r.text,\n 42|    title: r.title,\n 43|    version: r.version,\n 44|    validFrom: r.valid_from,\n 45|    validTo: r.valid_to,\n 46|    audience: r.audience,\n 47|    vector: readVector(r.vector),\n 48|  }));\n 49|}\n 50|export function exportIndex(): IndexDump {\n 51|  const db = appDb();\n 52|  const model = (\n 53|    db.prepare('SELECT value FROM meta WHERE key=?').get('index-model') as { value: string }\n 54|  ).value;\n 55|  const dimensions = Number(\n 56|    (db.prepare('SELECT value FROM meta WHERE key=?').get('index-dimensions') as { value: string })\n 57|      .value,\n 58|  );\n 59|  return {\n 60|    format: 1,\n 61|    model,\n 62|    dimensions,\n 63|    chunks: allChunks().map(({ vector, ...c }) => ({\n 64|      ...c,\n 65|      vectorBase64: vectorBuffer(vector!).toString('base64'),\n 66|    })),\n 67|  };\n 68|}\n 69|export function restoreIndex(index: IndexDump) {\n 70|  if (index.format !== 1 || index.model !== config.embeddingModel)\n 71|    throw new Error('The initial index uses a different model. Run npm run ingest.');\n 72|  const chunks = index.chunks.map(({ vectorBase64, ...c }) => ({\n 73|    ...c,\n 74|    vector: readVector(Buffer.from(vectorBase64, 'base64')),\n 75|  }));\n 76|  replaceChunks(chunks, { model: index.model, dimensions: index.dimensions });\n 77|  const db = appDb();\n 78|  db.transaction(() => {\n 79|    for (const c of chunks)\n 80|      db.prepare('INSERT OR REPLACE INTO embedding_cache VALUES(?,?)').run(\n 81|        embeddingKey(c.text),\n 82|        vectorBuffer(c.vector),\n 83|      );\n 84|  })();\n 85|}\n</file-view>",
