      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/retrieval/embeddings.ts\" start_line=\"1\" end_line=\"63\">\n  1|import OpenAI from 'openai';\n  2|import { createHash } from 'node:crypto';\n  3|import { appDb } from '../db';\n  4|import { config } from '../config';\n  5|export const dimensions = 1536;\n  6|export function vectorBuffer(vector: number[]) {\n  7|  return Buffer.from(new Float32Array(vector).buffer);\n  8|}\n  9|export function readVector(buffer: Buffer) {\n 10|  return Array.from(\n 11|    new Float32Array(buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)),\n 12|  );\n 13|}\n 14|export function embeddingKey(text: string) {\n 15|  return createHash('sha256')\n 16|    .update(`${config.embeddingModel}:${dimensions}:text-v1:${text}`)\n 17|    .digest('hex');\n 18|}\n 19|export class MissingOpenAIKeyError extends Error {\n 20|  constructor() {\n 21|    super(\n 22|      'Set OPENAI_API_KEY in .env.local or the environment to use the agent and semantic search, then restart the services.',\n 23|    );\n 24|    this.name = 'MissingOpenAIKeyError';\n 25|  }\n 26|}\n 27|export function openai() {\n 28|  if (!process.env.OPENAI_API_KEY?.trim()) throw new MissingOpenAIKeyError();\n 29|  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY, maxRetries: 2, timeout: 45000 });\n 30|}\n 31|export async function embedTexts(texts: string[]): Promise<number[][]> {\n 32|  const db = appDb(),\n 33|    result: number[][] = new Array(texts.length),\n 34|    missing: { index: number; text: string; key: string }[] = [];\n 35|  texts.forEach((text, index) => {\n 36|    const key = embeddingKey(text),\n 37|      cached = db.prepare('SELECT vector FROM embedding_cache WHERE key=?').get(key) as\n 38|        { vector: Buffer } | undefined;\n 39|    if (cached) result[index] = readVector(cached.vector);\n 40|    else missing.push({ index, text, key });\n 41|  });\n 42|  for (let offset = 0; offset < missing.length; offset += 48) {\n 43|    const batch = missing.slice(offset, offset + 48);\n 44|    const response = await openai().embeddings.create({\n 45|      model: config.embeddingModel,\n 46|      input: batch.map((x) => x.text),\n 47|      dimensions,\n 48|      encoding_format: 'float',\n 49|    });\n 50|    for (const item of response.data) {\n 51|      const target = batch[item.index];\n 52|      if (!target || item.embedding.length !== dimensions)\n 53|        throw new Error('Unexpected dimensions returned by the embeddings API.');\n 54|      result[target.index] = item.embedding;\n 55|      db.prepare('INSERT OR REPLACE INTO embedding_cache VALUES(?,?)').run(\n 56|        target.key,\n 57|        vectorBuffer(item.embedding),\n 58|      );\n 59|    }\n 60|    if (batch.some((x) => !result[x.index])) throw new Error('Incomplete embeddings response.');\n 61|  }\n 62|  return result;\n 63|}\n</file-view>",
