      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/ingestion/pipeline.ts\" start_line=\"1\" end_line=\"43\">\n  1|import fs from 'node:fs';\n  2|import path from 'node:path';\n  3|import { gzipSync } from 'node:zlib';\n  4|import { config } from '../config';\n  5|import type { Chunk, DocumentRecord } from '../types';\n  6|import { chunkDocument } from './chunker';\n  7|import { embedTexts, dimensions } from '../retrieval/embeddings';\n  8|import { replaceChunks, exportIndex } from '../retrieval/store';\n  9|export function documents(): DocumentRecord[] {\n 10|  return JSON.parse(fs.readFileSync(path.resolve('fixtures/documents/manifest.json'), 'utf8'));\n 11|}\n 12|export function readDocument(doc: DocumentRecord) {\n 13|  const root = path.resolve('fixtures/documents');\n 14|  const filename = path.resolve(root, doc.file);\n 15|  if (!filename.startsWith(root + path.sep)) throw new Error('Invalid document path.');\n 16|  let text = fs.readFileSync(filename, 'utf8');\n 17|  if (filename.endsWith('.html'))\n 18|    text = text\n 19|      .replace(/<script[\\s\\S]*?<\\/script>/gi, '')\n 20|      .replace(/<[^>]+>/g, ' ')\n 21|      .replace(/&nbsp;/g, ' ')\n 22|      .replace(/&amp;/g, '&');\n 23|  return text.replace(/\\r\\n/g, '\\n');\n 24|}\n 25|export async function ingest(onProgress: (value: string) => void = () => {}) {\n 26|  const docs = documents();\n 27|  const chunks: Chunk[] = docs.flatMap((doc) => chunkDocument(doc, readDocument(doc)));\n 28|  onProgress(`${docs.length} documents · ${chunks.length} chunks`);\n 29|  const vectors = await embedTexts(chunks.map((c) => c.text));\n 30|  const complete = chunks.map((c, i) => ({ ...c, vector: vectors[i] }));\n 31|  replaceChunks(complete, { model: config.embeddingModel, dimensions });\n 32|  onProgress('Index updated.');\n 33|  return {\n 34|    documents: docs.length,\n 35|    chunks: complete.length,\n 36|    model: config.embeddingModel,\n 37|    dimensions,\n 38|  };\n 39|}\n 40|export function saveInitialIndex() {\n 41|  fs.mkdirSync('fixtures/embeddings', { recursive: true });\n 42|  fs.writeFileSync('fixtures/embeddings/index.json.gz', gzipSync(JSON.stringify(exportIndex())));\n 43|}\n</file-view>",
