      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/simulator/server.ts\" start_line=\"1\" end_line=\"166\">\n  1|import http from 'node:http';\n  2|import { z } from 'zod';\n  3|import { config } from '../src/config';\n  4|import { sign, equal, HttpError } from '../src/auth';\n  5|import { people, person } from '../src/people';\n  6|import { bankDb } from './db';\n  7|import { seedBank } from './seed';\n  8|import {\n  9|  listAccounts,\n 10|  operationByReference,\n 11|  profiles,\n 12|  scenario,\n 13|  setScenario,\n 14|  transfer,\n 15|} from './bank';\n 16|const db = bankDb();\n 17|if (!(db.prepare('SELECT COUNT(*) AS n FROM accounts').get() as { n: number }).n) seedBank();\n 18|const transferSchema = z\n 19|  .object({\n 20|    fromAccountId: z.string(),\n 21|    toAccountId: z.string(),\n 22|    amountCents: z.number().int().positive().max(10000000),\n 23|    concept: z.string().max(200),\n 24|    reference: z.string().min(1).max(120),\n 25|  })\n 26|  .strict();\n 27|const server = http.createServer(async (req, res) => {\n 28|  const reply = (status: number, data: unknown) => {\n 29|    if (!res.destroyed) {\n 30|      res.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' });\n 31|      res.end(JSON.stringify(data));\n 32|    }\n 33|  };\n 34|  try {\n 35|    const url = new URL(req.url || '/', 'http://bank.local');\n 36|    if (url.pathname === '/health') {\n 37|      reply(200, { ok: true, service: 'banana-bank', version: 1 });\n 38|      return;\n 39|    }\n 40|    let raw = '';\n 41|    for await (const chunk of req) {\n 42|      raw += chunk;\n 43|      if (raw.length > 32768) throw new HttpError(413, 'Request too large.');\n 44|    }\n 45|    const body = raw ? JSON.parse(raw) : {};\n 46|    if (url.pathname.startsWith('/admin/')) {\n 47|      const token = String(req.headers.authorization || '').replace(/^Bearer /, '');\n 48|      if (!equal(token, config.adminSecret))\n 49|        throw new HttpError(403, 'Invalid administrator credential.');\n 50|      if (url.pathname === '/admin/reset' && req.method === 'POST') {\n 51|        seedBank();\n 52|        reply(200, { ok: true });\n 53|        return;\n 54|      }\n 55|      if (url.pathname === '/admin/scenario' && req.method === 'POST') {\n 56|        const input = z\n 57|          .object({ profile: z.enum(profiles), seed: z.number().int().optional() })\n 58|          .parse(body);\n 59|        setScenario(input.profile, input.seed);\n 60|        reply(200, scenario());\n 61|        return;\n 62|      }\n 63|      if (url.pathname === '/admin/snapshot' && req.method === 'GET') {\n 64|        reply(200, {\n 65|          accounts: db.prepare('SELECT * FROM accounts ORDER BY id').all(),\n 66|          operations: db.prepare('SELECT * FROM operations ORDER BY createdAt,id').all(),\n 67|          movements: db.prepare('SELECT * FROM movements ORDER BY createdAt,id').all(),\n 68|          scenario: scenario(),\n 69|        });\n 70|        return;\n 71|      }\n 72|      throw new HttpError(404, 'Route not found.');\n 73|    }\n 74|    const actor = String(req.headers['x-bank-actor'] || '');\n 75|    const timestamp = String(req.headers['x-bank-time'] || '');\n 76|    const signature = String(req.headers['x-bank-signature'] || '');\n 77|    const payload = [req.method, req.url, actor, timestamp, raw].join('\\n');\n 78|    if (\n 79|      !person(actor) ||\n 80|      !Number.isFinite(Number(timestamp)) ||\n 81|      Math.abs(Date.now() - Number(timestamp)) > 60000 ||\n 82|      !equal(signature, sign(payload, config.serviceSecret))\n 83|    )\n 84|      throw new HttpError(401, 'Invalid actor context.');\n 85|    if (url.pathname === '/v1/accounts' && req.method === 'GET') {\n 86|      reply(200, listAccounts(actor));\n 87|      return;\n 88|    }\n 89|    if (url.pathname === '/v1/contacts' && req.method === 'GET') {\n 90|      reply(\n 91|        200,\n 92|        db\n 93|          .prepare('SELECT id,userId,label,iban FROM accounts WHERE userId!=? ORDER BY userId')\n 94|          .all(actor)\n 95|          .map((a: any) => ({ ...a, name: person(a.userId)?.name })),\n 96|      );\n 97|      return;\n 98|    }\n 99|    if (url.pathname === '/v1/movements' && req.method === 'GET') {\n100|      reply(\n101|        200,\n102|        db\n103|          .prepare(\n104|            'SELECT m.* FROM movements m JOIN accounts a ON a.id=m.accountId WHERE a.userId=? ORDER BY m.createdAt DESC,m.id LIMIT 100',\n105|          )\n106|          .all(actor),\n107|      );\n108|      return;\n109|    }\n110|    if (url.pathname === '/v1/transfers' && req.method === 'POST') {\n111|      const { reference, ...input } = transferSchema.parse(body);\n112|      const result = transfer(actor, reference, input);\n113|      if (result.fault === 'reject-before') {\n114|        reply(503, {\n115|          error: 'Service temporarily unavailable',\n116|          code: 'temporarily_unavailable',\n117|        });\n118|        return;\n119|      }\n120|      if (result.fault === 'lost-response' || result.fault === 'read-unavailable') {\n121|        reply(504, { error: 'Upstream request timed out', code: 'upstream_timeout' });\n122|        return;\n123|      }\n124|      if (result.fault === 'slow-response')\n125|        await new Promise((resolve) => setTimeout(resolve, 2600));\n126|      reply(200, { ...result.operation, replay: result.replay });\n127|      return;\n128|    }\n129|    if (url.pathname.startsWith('/v1/operations/') && req.method === 'GET') {\n130|      const op = operationByReference(\n131|        actor,\n132|        decodeURIComponent(url.pathname.slice('/v1/operations/'.length)),\n133|      );\n134|      if (!op) throw new HttpError(404, 'Operation not found.');\n135|      reply(200, op);\n136|      return;\n137|    }\n138|    if (url.pathname === '/v1/operator/customer' && req.method === 'GET') {\n139|      if (person(actor)?.role !== 'operator') throw new HttpError(403, 'Operator role required.');\n140|      const customer = url.searchParams.get('id') || '';\n141|      if (!people.some((p) => p.id === customer && p.role === 'customer'))\n142|        throw new HttpError(404, 'Customer not found.');\n143|      reply(200, {\n144|        accounts: listAccounts(customer),\n145|        operations: db\n146|          .prepare('SELECT * FROM operations WHERE userId=? ORDER BY createdAt DESC')\n147|          .all(customer),\n148|      });\n149|      return;\n150|    }\n151|    throw new HttpError(404, 'Route not found.');\n152|  } catch (e) {\n153|    if (e instanceof HttpError) reply(e.status, { error: e.message });\n154|    else if (e instanceof z.ZodError || e instanceof SyntaxError)\n155|      reply(400, { error: 'Invalid request data.' });\n156|    else {\n157|      console.error('bank_request_failed', e instanceof Error ? e.name : 'unknown');\n158|      reply(500, { error: 'Internal simulator error.' });\n159|    }\n160|  }\n161|});\n162|server.listen(config.bankPort, '127.0.0.1', () =>\n163|  console.log(`Simulated bank: http://127.0.0.1:${config.bankPort}`),\n164|);\n165|for (const signal of ['SIGTERM', 'SIGINT'] as const)\n166|  process.on(signal, () => server.close(() => process.exit(0)));\n</file-view>",
