      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/simulator/seed.ts\" start_line=\"1\" end_line=\"133\">\n  1|import { bankDb } from './db';\n  2|import { people } from '../src/people';\n  3|export function seedBank() {\n  4|  const db = bankDb();\n  5|  db.transaction(() => {\n  6|    db.exec(\n  7|      'DELETE FROM movements; DELETE FROM operations; DELETE FROM accounts; DELETE FROM scenario;',\n  8|    );\n  9|    const putAccount = db.prepare('INSERT INTO accounts VALUES(?,?,?,?,?)');\n 10|    const putMovement = db.prepare('INSERT INTO movements VALUES(?,?,?,?,?,?)');\n 11|    const customers = people.filter((p) => p.role === 'customer');\n 12|    customers.forEach((p, i) => {\n 13|      const accountId = `acc-${p.id}`;\n 14|      const opening = p.id === 'diego' ? 7500 : 240000 + i * 31000;\n 15|      putAccount.run(\n 16|        accountId,\n 17|        p.id,\n 18|        i % 2 ? 'Horizon account' : 'Aurora account',\n 19|        `ES91 2100 0418 45${String(i + 1).padStart(10, '0')}`,\n 20|        opening,\n 21|      );\n 22|      putMovement.run(\n 23|        `opening-${p.id}`,\n 24|        accountId,\n 25|        null,\n 26|        opening,\n 27|        'Opening balance',\n 28|        '2026-08-01T09:00:00.000Z',\n 29|      );\n 30|      for (let j = 0; j < 5; j++) {\n 31|        const amount = j === 0 ? 175000 : -(1000 + (i + j) * 175);\n 32|        db.prepare('UPDATE accounts SET balanceCents=balanceCents+? WHERE id=?').run(\n 33|          amount,\n 34|          accountId,\n 35|        );\n 36|        putMovement.run(\n 37|          `movement-${p.id}-${j}`,\n 38|          accountId,\n 39|          null,\n 40|          amount,\n 41|          ['September salary', 'Groceries', 'Internet bill', 'Coffee shop', 'Transport'][j],\n 42|          `2026-09-${String(2 + j * 3).padStart(2, '0')}T10:00:00.000Z`,\n 43|        );\n 44|      }\n 45|      if (p.id === 'diego') {\n 46|        const current = (\n 47|          db.prepare('SELECT balanceCents FROM accounts WHERE id=?').get(accountId) as {\n 48|            balanceCents: number;\n 49|          }\n 50|        ).balanceCents;\n 51|        putMovement.run(\n 52|          'diego-savings',\n 53|          accountId,\n 54|          null,\n 55|          7500 - current,\n 56|          'Transfer to external savings',\n 57|          '2026-09-20T10:00:00.000Z',\n 58|        );\n 59|        db.prepare('UPDATE accounts SET balanceCents=7500 WHERE id=?').run(accountId);\n 60|      }\n 61|      if (i % 2 === 0) {\n 62|        const id = `acc-${p.id}-savings`;\n 63|        putAccount.run(\n 64|          id,\n 65|          p.id,\n 66|          'Personal savings',\n 67|          `ES22 2100 0418 46${String(i + 1).padStart(10, '0')}`,\n 68|          100000 + i * 20000,\n 69|        );\n 70|        putMovement.run(\n 71|          `opening-savings-${p.id}`,\n 72|          id,\n 73|          null,\n 74|          100000 + i * 20000,\n 75|          'Savings account opening',\n 76|          '2026-08-01T09:00:00.000Z',\n 77|        );\n 78|      }\n 79|    });\n 80|    const at = '2026-09-23T16:41:12.000Z';\n 81|    db.prepare('INSERT INTO operations VALUES(?,?,?,?,?,?,?,?,?)').run(\n 82|      'op-historic-lucia',\n 83|      'lucia',\n 84|      'ref-historic-lucia',\n 85|      'acc-lucia',\n 86|      'acc-bruno',\n 87|      8500,\n 88|      'Team dinner',\n 89|      at,\n 90|      'completed',\n 91|    );\n 92|    for (const [account, amount] of [\n 93|      ['acc-lucia', -8500],\n 94|      ['acc-bruno', 8500],\n 95|    ] as const) {\n 96|      db.prepare('UPDATE accounts SET balanceCents=balanceCents+? WHERE id=?').run(amount, account);\n 97|      putMovement.run(\n 98|        `historic-${account}`,\n 99|        account,\n100|        'op-historic-lucia',\n101|        amount,\n102|        'Transfer · Team dinner',\n103|        at,\n104|      );\n105|    }\n106|    db.prepare('INSERT INTO operations VALUES(?,?,?,?,?,?,?,?,?)').run(\n107|      'op-historic-elena',\n108|      'elena',\n109|      'ref-historic-elena',\n110|      'acc-elena',\n111|      'acc-hugo',\n112|      2500,\n113|      'Transfer to Hugo',\n114|      '2026-09-23T16:42:10.000Z',\n115|      'completed',\n116|    );\n117|    for (const [account, amount] of [\n118|      ['acc-elena', -2500],\n119|      ['acc-hugo', 2500],\n120|    ] as const) {\n121|      db.prepare('UPDATE accounts SET balanceCents=balanceCents+? WHERE id=?').run(amount, account);\n122|      putMovement.run(\n123|        `historic-${account}`,\n124|        account,\n125|        'op-historic-elena',\n126|        amount,\n127|        'Transfer · Transfer to Hugo',\n128|        '2026-09-23T16:42:10.000Z',\n129|      );\n130|    }\n131|    db.prepare('INSERT INTO scenario VALUES(1,?,?,0,0)').run('intermittent', 17);\n132|  })();\n133|}\n</file-view>",
