      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/banking/client.ts\" start_line=\"1\" end_line=\"40\">\n  1|import { config } from '../config';\n  2|import { sign } from '../auth';\n  3|export class BankError extends Error {\n  4|  constructor(\n  5|    public status: number,\n  6|    message: string,\n  7|  ) {\n  8|    super(message);\n  9|  }\n 10|}\n 11|export async function bankRequest<T>(\n 12|  userId: string,\n 13|  path: string,\n 14|  method = 'GET',\n 15|  body?: unknown,\n 16|): Promise<T> {\n 17|  const raw = body === undefined ? '' : JSON.stringify(body),\n 18|    timestamp = String(Date.now());\n 19|  const signature = sign([method, path, userId, timestamp, raw].join('\\n'), config.serviceSecret);\n 20|  let response: Response;\n 21|  try {\n 22|    response = await fetch(`${config.bankUrl}${path}`, {\n 23|      method,\n 24|      headers: {\n 25|        'Content-Type': 'application/json',\n 26|        'x-bank-actor': userId,\n 27|        'x-bank-time': timestamp,\n 28|        'x-bank-signature': signature,\n 29|      },\n 30|      body: raw || undefined,\n 31|      signal: AbortSignal.timeout(config.bankTimeoutMs),\n 32|      cache: 'no-store',\n 33|    });\n 34|  } catch {\n 35|    throw new BankError(504, 'No response received from the bank.');\n 36|  }\n 37|  const data = await response.json();\n 38|  if (!response.ok) throw new BankError(response.status, data.error || 'Bank service error.');\n 39|  return data as T;\n 40|}\n</file-view>",
