        '<file-view path="/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidat…',
      text: "<file-view path=\"/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/simulator/bank.ts\" start_line=\"1\" end_line=\"140\">\n  1|import { randomUUID } from 'node:crypto';\n  2|import { bankDb } from './db';\n  3|import { HttpError } from '../src/auth';\n  4|import type { Account, Operation, TransferInput } from '../src/types';\n  5|import { person } from '../src/people';\n  6|export const profiles = [\n  7|  'normal',\n  8|  'intermittent',\n  9|  'reject-before',\n 10|  'lost-response',\n 11|  'slow-response',\n 12|  'read-unavailable',\n 13|] as const;\n 14|export type Profile = (typeof profiles)[number];\n 15|export function setScenario(profile: Profile, seed = 17) {\n 16|  if (!profiles.includes(profile)) throw new HttpError(400, 'Unknown scenario profile.');\n 17|  bankDb()\n 18|    .prepare('UPDATE scenario SET profile=?,seed=?,counter=0,read_failures=0 WHERE id=1')\n 19|    .run(profile, seed);\n 20|}\n 21|export function scenario() {\n 22|  return bankDb().prepare('SELECT * FROM scenario WHERE id=1').get() as {\n 23|    profile: Profile;\n 24|    seed: number;\n 25|    counter: number;\n 26|    read_failures: number;\n 27|  };\n 28|}\n 29|export function listAccounts(userId: string) {\n 30|  return bankDb()\n 31|    .prepare('SELECT * FROM accounts WHERE userId=? ORDER BY id')\n 32|    .all(userId) as Account[];\n 33|}\n 34|export function transfer(\n 35|  userId: string,\n 36|  reference: string,\n 37|  input: TransferInput,\n 38|): { operation: Operation; fault: string | null; replay: boolean } {\n 39|  if (person(userId)?.role !== 'customer')\n 40|    throw new HttpError(403, 'Only the account holder can transfer funds.');\n 41|  if (!reference || reference.length > 120)\n 42|    throw new HttpError(400, 'An operation reference is required.');\n 43|  const db = bankDb();\n 44|  return db.transaction(() => {\n 45|    const previous = db\n 46|      .prepare('SELECT * FROM operations WHERE userId=? AND reference=?')\n 47|      .get(userId, reference) as Operation | undefined;\n 48|    if (previous) {\n 49|      if (\n 50|        previous.fromAccountId !== input.fromAccountId ||\n 51|        previous.toAccountId !== input.toAccountId ||\n 52|        previous.amountCents !== input.amountCents ||\n 53|        previous.concept !== input.concept\n 54|      )\n 55|        throw new HttpError(409, 'The reference already belongs to a different operation.');\n 56|      return { operation: previous, fault: null, replay: true };\n 57|    }\n 58|    const from = db\n 59|      .prepare('SELECT * FROM accounts WHERE id=? AND userId=?')\n 60|      .get(input.fromAccountId, userId) as Account | undefined;\n 61|    const to = db.prepare('SELECT * FROM accounts WHERE id=?').get(input.toAccountId) as\n 62|      Account | undefined;\n 63|    if (!from) throw new HttpError(403, 'Source account not authorized.');\n 64|    if (!to || to.id === from.id) throw new HttpError(400, 'Invalid destination account.');\n 65|    if (\n 66|      !Number.isSafeInteger(input.amountCents) ||\n 67|      input.amountCents <= 0 ||\n 68|      input.amountCents > 10000000\n 69|    )\n 70|      throw new HttpError(400, 'Amount outside simulator limits.');\n 71|    if (from.balanceCents < input.amountCents) throw new HttpError(422, 'Insufficient funds.');\n 72|    const s = scenario();\n 73|    const counter = s.counter + 1;\n 74|    db.prepare('UPDATE scenario SET counter=? WHERE id=1').run(counter);\n 75|    let fault: string | null = null;\n 76|    if (s.profile === 'intermittent' && (counter + s.seed) % 4 === 0) fault = 'lost-response';\n 77|    else if (s.profile !== 'normal' && s.profile !== 'intermittent' && counter === 1)\n 78|      fault = s.profile;\n 79|    if (fault === 'reject-before')\n 80|      return { operation: undefined as unknown as Operation, fault, replay: false };\n 81|    const operation: Operation = {\n 82|      ...input,\n 83|      id: randomUUID(),\n 84|      userId,\n 85|      reference,\n 86|      createdAt: new Date().toISOString(),\n 87|      status: 'completed',\n 88|    };\n 89|    db.prepare('UPDATE accounts SET balanceCents=balanceCents-? WHERE id=?').run(\n 90|      input.amountCents,\n 91|      from.id,\n 92|    );\n 93|    db.prepare('UPDATE accounts SET balanceCents=balanceCents+? WHERE id=?').run(\n 94|      input.amountCents,\n 95|      to.id,\n 96|    );\n 97|    db.prepare('INSERT INTO operations VALUES(?,?,?,?,?,?,?,?,?)').run(\n 98|      operation.id,\n 99|      userId,\n100|      reference,\n101|      from.id,\n102|      to.id,\n103|      input.amountCents,\n104|      input.concept,\n105|      operation.createdAt,\n106|      'completed',\n107|    );\n108|    const stmt = db.prepare('INSERT INTO movements VALUES(?,?,?,?,?,?)');\n109|    stmt.run(\n110|      randomUUID(),\n111|      from.id,\n112|      operation.id,\n113|      -input.amountCents,\n114|      `Transfer · ${input.concept}`,\n115|      operation.createdAt,\n116|    );\n117|    stmt.run(\n118|      randomUUID(),\n119|      to.id,\n120|      operation.id,\n121|      input.amountCents,\n122|      `Transfer · ${input.concept}`,\n123|      operation.createdAt,\n124|    );\n125|    if (fault === 'read-unavailable')\n126|      db.prepare('UPDATE scenario SET read_failures=1 WHERE id=1').run();\n127|    return { operation, fault, replay: false };\n128|  })();\n129|}\n130|export function operationByReference(userId: string, reference: string) {\n131|  const db = bankDb();\n132|  const s = scenario();\n133|  if (s.read_failures > 0) {\n134|    db.prepare('UPDATE scenario SET read_failures=read_failures-1 WHERE id=1').run();\n135|    throw new HttpError(503, 'Query temporarily unavailable.');\n136|  }\n137|  return db\n138|    .prepare('SELECT * FROM operations WHERE userId=? AND reference=?')\n139|    .get(userId, reference) as Operation | undefined;\n140|}\n</file-view>",
