            "import { createHash } from 'node:crypto';\nimport type { Chunk, DocumentRecord } from '../types';\nfunction splitLong(paragraph: string): string[] {\n  if (paragraph.length <= 1400) return [paragraph];\n  const sentences = paragraph.match(/[^.!?]+[.!?]+|\\S[^.!?]*$/g) || [paragraph];\n  const parts: string[] = [];\n  let buffer = '';\n  for (const sentence of sentences) {\n    if (buffer.length + sentence.length > 700 && buffer) {\n      parts.push(buffer.trim());\n      buffer = '';\n    }\n    buffer += sentence;\n    while (buffer.length > 700) {\n      parts.push(buffer.slice(0, 700).trim());\n      buffer = buffer.slice(700);\n    }\n  }\n  if (buffer.trim()) parts.push(buffer.trim());\n  return parts;\n}\nexport function chunkDocument(doc: DocumentRecord, text: string): Chunk[] {\n  const paragraphs = text\n    .split(/\\n\\s*\\n/)\n    .map((p) => p.trim())\n    .filter(Boolean);\n  const groups: string[] = [];\n  let buffer = '';\n  for (const paragraph of paragraphs) {\n    if (paragraph.length > 700) {\n      if (buffer) {\n        groups.push(buffer);\n        buffer = '';\n      }\n      groups.push(...splitLong(paragraph));\n    } else if (buffer && buffer.length + paragraph.length + 2 > 700) {\n      groups.push(buffer);\n      buffer = paragraph;\n    } else {\n      buffer = buffer ? `${buffer}\\n\\n${paragraph}` : paragraph;\n    }\n  }\n  if (buffer) groups.push(buffer);\n  return groups.map((group, index) => {\n    const body = `${doc.title} (${doc.id} v${doc.version})\\n${group}`;\n    return {\n      id: createHash('sha256').update(`${doc.id}:${index}:${body}`).digest('hex').slice(0, 24),\n      documentId: doc.id,\n      text: body,\n      title: doc.title,\n      version: doc.version,\n      validFrom: doc.validFrom,\n      validTo: doc.validTo,\n      audience: doc.audience,\n    };\n  });\n}\n",
