            "// Verifica el visor de sesiones (layout compacto): file://, sin red, interacciones, fps y capturas.\nimport { chromium } from 'playwright';\nimport { pathToFileURL } from 'node:url';\n\nconst viewer = pathToFileURL(\n  '/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/submission/ai-sessions-viewer/index.html',\n).href;\nconst out = '/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/submission/evidencias/despues';\n\nconst browser = await chromium.launch();\nconst page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });\nconst external = [];\npage.on('request', (r) => { if (!r.url().startsWith('file://')) external.push(r.url()); });\nconst errors = [];\npage.on('pageerror', (e) => errors.push(String(e)));\n\nawait page.goto(viewer);\nawait page.waitForSelector('.session-item');\nawait page.waitForTimeout(1500);\nawait page.screenshot({ path: `${out}/18-visor-sesiones-inicio.png` });\n\nconst loadMs = await page.evaluate(() => window.__lastLoadMs);\nconsole.log('load ms righteous-nest:', loadMs);\nconst counts = await page.evaluate(() => ({\n  nodes: document.querySelectorAll('g.node').length,\n  links: document.querySelectorAll('path.link').length,\n  forks: document.querySelectorAll('path.link.fork').length,\n  twigs: document.querySelectorAll('path.link.twig').length,\n  chapters: document.querySelectorAll('#chapter-strip .ch').length,\n  lanes: document.querySelectorAll('.lane-label').length,\n  clusters: document.querySelectorAll('g.cluster').length,\n}));\nconsole.log('counts:', JSON.stringify(counts));\n\n// fps durante un pan programático de 1 s\nconst fps = await page.evaluate(() => new Promise((res) => {\n  const svg = document.querySelector('#graph');\n  let frames = 0;\n  const t0 = performance.now();\n  const tick = () => {\n    frames++;\n    const tr = d3.zoomTransform(svg);\n    d3.select(svg).call(d3.zoom().on('zoom', () => {}).transform, tr.translate(-30, 0));\n    // más simple: aplicar transform directo sobre el root\n    document.querySelector('#graph > g').setAttribute('transform', `translate(${tr.x - 30},${tr.y}) scale(${tr.k})`);\n    if (performance.now() - t0 < 1000) requestAnimationFrame(tick);\n    else res(frames);\n  };\n  requestAnimationFrame(tick);\n}));\nconsole.log('fps durante pan ~:', fps);\n\n// selecciona un tool_call de la lane sidekick\nconst picked = await page.evaluate(() => {\n  const s = window.__SESSION_DATA['righteous-nest'];\n  const n = s.nodes.find((x) => x.lane === 'sidekick' && x.kind === 'tool_call');\n  return { id: n.id, title: n.title };\n});\nawait page.evaluate((id) => {\n  document.querySelectorAll('g.node').forEach((g) => {\n    if (g.__data__ && g.__data__.id === id) g.dispatchEvent(new MouseEvent('click', { bubbles: true }));\n  });\n}, picked.id);\nawait page.waitForTimeout(300);\nawait page.screenshot({ path: `${out}/18-visor-sesiones-grafo.png` });\n\n// búsqueda + detalle\nawait page.fill('#search', 'dispatch.ts');\nawait page.waitForTimeout(300);\nconsole.log('search:', (await page.textContent('#search-status')).trim());\nconsole.log('detail:', (await page.evaluate(() => document.querySelector('#detail-head').textContent)).trim().slice(0, 100));\nawait page.screenshot({ path: `${out}/18-visor-sesiones-detalle.png` });\n\n// zoom 0.35 con varias calles\nawait page.evaluate(() => {\n  const svg = document.querySelector('#graph');\n  const g = document.querySelector('#graph > g');\n  g.setAttribute('transform', 'translate(120,60) scale(0.35)');\n});\nawait page.waitForTimeout(300);\nawait page.screenshot({ path: `${out}/18-visor-sesiones-minimapa.png` });\n\nconsole.log('external requests:', external.length ? external : 'none');\nconsole.log('page errors:', errors.length ? errors : 'none');\nawait browser.close();\n",
